{{!-- Styling parameters: class, titleClass, descriptionClass, formClass, inputClass, buttonClass --}}
{{#with this as |ghostcnStyles|}}
{{!--
  Component: Newsletter Form
  Usage: {{> "components/newsletter-form" title="Subscribe to our newsletter" description="Get the latest posts delivered right to your inbox."}}
--}}
{{#if @site.members_enabled}}
{{#unless @site.members_invite_only}}
{{#if @site.allow_self_signup}}
{{#unless @member}}
<section class="gh-newsletter-form{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}">
    <div class="gh-newsletter-heading">
        <h3 class="gh-newsletter-title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">
            {{#if title}}{{title}}{{else}}Subscribe to our newsletter{{/if}}
        </h3>
        <p class="gh-newsletter-desc{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">
            {{#if description}}{{description}}{{else}}Get the latest stories, news, and perspectives delivered directly to your inbox.{{/if}}
        </p>
    </div>

    {{!-- Ghost native members form handling --}}
    {{#if @site.portal_signup_checkbox_required}}
    <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/signup" data-portal="signup">Subscribe</a>
    {{else}}
    <form data-members-form="subscribe" class="gh-newsletter-fields{{#if ghostcnStyles.formClass}} {{ghostcnStyles.formClass}}{{/if}}">
        <input
            data-members-email
            type="email"
            aria-label="Email address"
            autocomplete="email"
            required
            placeholder="jamie@example.com"
            class="gh-newsletter-input{{#if ghostcnStyles.inputClass}} {{ghostcnStyles.inputClass}}{{/if}}"
        />
        <button type="submit" class="gh-newsletter-btn{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}">
            <span class="button-text">Subscribe</span>
        </button>

        {{!-- Ghost automatic states (hidden by default, shown via Ghost Portal JS) --}}
        <div class="gh-newsletter-msg-success message-success" role="status" data-members-success>
            ✓ Check your inbox to confirm your subscription!
        </div>
        <div class="gh-newsletter-msg-error message-error" role="alert" data-members-error>
            ✕ Please enter a valid email address.
        </div>
    </form>
    {{/if}}
</section>
{{/unless}}
{{/if}}
{{/unless}}
{{/if}}
{{/with}}

/* ghostcn: Newsletter Form Styles */
.gh-newsletter-form {
    box-sizing: border-box;
    font-family: inherit;
    font-size: 16px;
    line-height: 1.5;
    isolation: isolate;
    background-color: var(--card, #ffffff);
    color: var(--card-foreground, #09090b);
    border: 1px solid var(--border, #e4e4e7);
    border-radius: min(var(--radius, 0.5em), 1.5em);
    padding: 2em;
    text-align: center;
    max-width: 42em;
    margin: 2em auto;
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.gh-newsletter-form *,
.gh-newsletter-form *::before,
.gh-newsletter-form *::after {
    box-sizing: border-box;
}

.gh-newsletter-heading { margin-bottom: 1.5em; }

.gh-newsletter-title {
    font-size: 1.5em;
    font-weight: 700;
    letter-spacing: -0.025em;
    margin-bottom: 0.5em;
    color: var(--foreground, #09090b);
}

.gh-newsletter-desc {
    color: var(--muted-foreground, #71717a);
    font-size: 0.875em;
    line-height: 1.5;
    margin: 0 auto 1.5em;
    max-width: 28em;
}

.gh-newsletter-fields {
    display: flex;
    flex-direction: column;
    gap: 0.75em;
    max-width: 28em;
    margin: 0 auto;
    position: relative;
}

@media (min-width: 640px) {
    .gh-newsletter-fields {
        flex-direction: row;
    }
}

.gh-newsletter-input {
    flex: 1;
    padding: 0.625em 1em;
    background-color: var(--background, #ffffff);
    color: var(--foreground, #09090b);
    border: 1px solid var(--input, #e4e4e7);
    border-radius: var(--radius, 0.5em);
    font-size: 0.875em;
    outline: none;
    transition: box-shadow 0.15s ease, border-color 0.15s ease;
}

.gh-newsletter-input:focus {
    border-color: var(--ring, #18181b);
    box-shadow: 0 0 0 2px var(--ring, #18181b);
}

.gh-newsletter-btn {
    background-color: var(--primary, var(--ghost-accent-color, #18181b));
    color: var(--primary-foreground, #ffffff);
    padding: 0.625em 1.5em;
    border-radius: var(--radius, 0.5em);
    font-size: 0.875em;
    font-weight: 500;
    border: none;
    cursor: pointer;
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    transition: opacity 0.15s ease;
}

.gh-newsletter-btn:hover {
    opacity: 0.9;
}

.gh-newsletter-msg-success,
.gh-newsletter-msg-error {
    display: none;
    position: absolute;
    bottom: -1.75em;
    left: 0;
    right: 0;
    font-size: 0.75em;
    font-weight: 500;
}

.gh-newsletter-fields.success .gh-newsletter-msg-success,
.gh-newsletter-fields.error .gh-newsletter-msg-error {
    display: block;
}

.gh-newsletter-form .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.gh-newsletter-msg-success {
    color: #16a34a;
}

.gh-newsletter-msg-error {
    color: #dc2626;
}
